/* 只读设计原型：所有操作只改变此页面内存，不调用引擎、系统或配置文件。 */
const variants={A:'浅色画廊',B:'深色观画',C:'轻量控制台'};
const params=new URLSearchParams(location.search);
const state={variant:variants[params.get('variant')]?params.get('variant'):'A',painting:0,favorites:new Set(),auto:true,landscape:true,startup:true,time:'08:30',monitor:1,view:'today'};
const works=[
  {image:'assets/landscape-hunters.jpg',title:'Landscape with Hunters',artist:'Paul Bril',date:'1619',museum:'芝加哥艺术博物馆',medium:'布面油画',size:'2400 × 1620'},
  {image:'assets/tivoli-waterfalls.jpg',title:'The Waterfalls at Tivoli',artist:'Claude-Joseph Vernet',date:'1737',museum:'克利夫兰艺术博物馆',medium:'布面油画',size:'3400 × 2421'},
  {image:'assets/still-life.jpg',title:'Flowers and Fruit in a Porcelain Bowl',artist:'Juan de Zurbarán',date:'约 1645',museum:'芝加哥艺术博物馆',medium:'布面油画',size:'2400 × 1813'},
  {image:'assets/mountain-road.jpg',title:'Mountain Road with Travelers',artist:'Joos de Momper, II',date:'约 1615',museum:'芝加哥艺术博物馆',medium:'木板油画',size:'2400 × 1546'}
];
const paths={
  art:'<rect x="3" y="3" width="18" height="18" rx="1"/><path d="m5 16 5-6 4 4 3-4 3 6"/><path d="M8 7h.01"/>',
  heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  gear:'<path d="m10 3-.6 2.3-2 .9-2.1-.8-1.9 3.2L5 10.3v2.4l-1.6 1.7 1.9 3.2 2.1-.8 2 .9L10 20h4l.6-2.3 2-.9 2.1.8 1.9-3.2-1.6-1.7v-2.4l1.6-1.7-1.9-3.2-2.1.8-2-.9L14 3Z"/><circle cx="12" cy="11.5" r="3"/>',
  refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M19 12a7 7 0 0 0-12-5L4 10m1 2a7 7 0 0 0 12 5l3-3"/>',
  monitor:'<rect x="3" y="4" width="18" height="13" rx="1.5"/><path d="M8 21h8m-4-4v4"/>',
  expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',
  arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
  external:'<path d="M14 3h7v7M21 3l-9 9m-2-7H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  folder:'<path d="M3 7V5a1 1 0 0 1 1-1h5l2 3h9a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1Z"/>',
  library:'<path d="M4 3v18m5-18v18m5-16 5-2 5 16-5 2Z"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',
  minimize:'<path d="M4 12h16"/>',
  square:'<rect x="5" y="5" width="14" height="14"/>',
  more:'<circle cx="5" cy="12" r=".7"/><circle cx="12" cy="12" r=".7"/><circle cx="19" cy="12" r=".7"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
  leaf:'<path d="M20 3C10 2 3 7 5 15c7 5 15-2 15-12Z"/><path d="M4 21 16 8"/>'
};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.art}</svg>`;}
function chrome(){return `<div class="window-chrome"><span class="chrome-caption">${icon('art')}每日欧洲油画壁纸</span><span class="window-controls" aria-hidden="true">${icon('minimize')}${icon('square')}${icon('close')}</span></div>`;}
function brand(){return `<div class="brand"><span class="brand-mark">${icon('art')}</span><div class="brand-text"><strong>每日油画</strong><small>DAILY OIL PAINTING</small></div></div>`;}
function toggle(name){const on=state[name];return `<button class="switch ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${{auto:'自动更换',landscape:'不使用竖图',startup:'开机自动启动'}[name]}" data-toggle="${name}"></button>`;}
function heart(buttonClass='secondary'){return `<button class="${buttonClass} heart ${state.favorites.has(state.painting)?'is-saved':''}" data-action="favorite" aria-label="收藏当前画作">${icon('heart')}${buttonClass==='secondary'?` ${state.favorites.has(state.painting)?'已收藏':'收藏'}`:''}</button>`;}
function artStage(){const work=works[state.painting];return `<figure class="art-stage"><div class="art-backdrop" style="background-image:url('${work.image}')"></div><img class="painting" src="${work.image}" alt="${work.title}"><span class="stage-tag">${icon('monitor')}显示器 ${state.monitor} · ${state.monitor===1?'主屏':'副屏'}</span><button class="stage-expand" data-action="preview" aria-label="放大预览">${icon('expand')}</button><span class="stage-resolution">3840 × 2160</span></figure>`;}
function meta(){const w=works[state.painting];return `<h2 class="art-title">${w.title}</h2><p class="artist-line"><span>${w.artist}</span><i></i><span>${w.date}</span><i></i><span>${w.museum}</span></p>`;}
function recent(){return `<section class="recent"><div class="recent-header"><h3>最近的画作</h3><button class="text-btn" data-view="history">查看记录 ${icon('arrow')}</button></div><div class="recent-strip">${[1,3,2].map((index,i)=>`<button class="recent-item" data-painting="${index}"><img src="${works[index].image}" alt="${works[index].title}"><span><strong>${works[index].title}</strong><small>${i===0?'昨天':i===1?'11 月 09 日':'11 月 08 日'}</small></span></button>`).join('')}</div></section>`;}
function status(){return `<footer class="gallery-status"><span><i class="dot"></i>后台运行正常 · 单击托盘打开面板</span><span>${icon('library')}1,496 幅馆藏作品 · 1300–1800 年</span></footer>`;}
function row(key,title,note=''){return `<div class="switch-row"><div><div class="row-title">${title}</div>${note?`<small>${note}</small>`:''}</div>${toggle(key)}</div>`;}
function monitorTabs(){return `<div class="monitor-tabs"><div>${[1,2].map(n=>`<button class="monitor-tab ${state.monitor===n?'active':''}" data-monitor="${n}">${icon('monitor')}显示器 ${n}${n===1?' · 主屏':''}</button>`).join('')}</div><span>每块屏幕显示完整画作</span></div>`;}
function controls(){return `<button class="primary" data-action="change">${icon('refresh')}换一幅画</button>${heart()}<button class="text-btn" data-action="details">作品详情 ${icon('external')}</button>`;}
function timeOptions(){return ['06:30','07:30','08:30','12:00','18:00','21:00','23:00'].map(t=>`<option ${t===state.time?'selected':''}>${t}</option>`).join('');}
function settings(){return `<aside class="gallery-settings"><section class="auto-section"><h2 class="setting-heading">自动更换 ${icon('clock')}</h2><div class="schedule-top"><span>每天换一幅</span>${toggle('auto')}</div><div class="schedule-time"><span>每天</span>${state.time}</div><select class="time-selector" data-field="time" aria-label="每天更换时间">${timeOptions()}</select><p class="next-time">${state.auto?`下次更换 · 明天 ${state.time}`:'自动更换已暂停'}</p></section>${row('startup','开机自动启动','登录 Windows 后在后台运行')}${row('landscape','不使用竖图','让画作更适合横向屏幕')}<section class="display-section"><h2 class="setting-heading">屏幕与排版 ${icon('monitor')}</h2><div class="display-diagram"><div class="display-screen active">1</div><div class="display-screen">2</div></div><p class="display-note"><strong>2 块屏幕 · 均为 4K</strong><br>每屏独立适配，完整显示画作</p><button class="text-btn" data-action="settings" style="margin-top:12px">调整显示设置 ${icon('arrow')}</button></section><div class="settings-foot">${icon('leaf')} 每天一幅，在桌面遇见古典绘画。<br>公共领域馆藏 · 保留作品与博物馆署名</div></aside>`;}
function collection(){const favorite=state.view==='favorites';const ids=favorite?[...state.favorites]:[1,3,2,0];return `<section class="collection-content"><h2>${favorite?'我的收藏':'更换记录'}</h2><p>${favorite?'喜欢的画作，留在这里。':'最近出现在桌面上的画作。'}</p>${ids.length?`<div class="collection-grid">${ids.map(i=>`<button class="collection-item" data-painting="${i}"><img src="${works[i].image}" alt="${works[i].title}"><h3>${works[i].title}</h3><p>${works[i].artist} · ${works[i].date}</p></button>`).join('')}</div>`:`<p style="margin-top:80px;text-align:center">还没有收藏。点击画作旁的爱心，留下你喜欢的那一幅。</p>`}</section>`;}
function VariantA(){return `<section class="window gallery" aria-label="方案 A 浅色画廊">${chrome()}<div class="gallery-layout"><aside class="gallery-nav">${brand()}<nav><button class="nav-item ${state.view==='today'?'active':''}" data-view="today">${icon('art')}今日画作</button><button class="nav-item ${state.view==='favorites'?'active':''}" data-view="favorites">${icon('heart')}我的收藏${state.favorites.size?`<small>${state.favorites.size}</small>`:''}</button><button class="nav-item ${state.view==='history'?'active':''}" data-view="history">${icon('clock')}更换记录</button><div class="nav-divider"></div><button class="nav-item" data-action="settings">${icon('gear')}设置</button></nav><div class="nav-bottom"><p class="library-label">${icon('library')}欧洲古典绘画</p>4 家博物馆<br>1300—1800 年<div style="margin-top:15px"><i class="dot"></i>后台运行正常</div></div></aside><div class="gallery-main"><header class="gallery-top"><div><h1>${{today:'今日画作',favorites:'我的收藏',history:'更换记录'}[state.view]}</h1><p>2026 年 11 月 11 日 · 星期三</p></div><div class="top-actions"><span>${icon('check')}${state.landscape?'竖图已过滤':'所有画幅'}</span><span class="pill">${icon('monitor')}双屏适配</span><button class="icon-btn" data-action="settings" aria-label="设置">${icon('more')}</button></div></header>${state.view==='today'?`<div class="gallery-content"><section class="gallery-art">${artStage()}${monitorTabs()}<div class="art-meta">${meta()}</div><div class="gallery-actions">${controls()}</div>${recent()}</section>${settings()}</div>`:collection()}${status()}</div></div></section>`;}
function VariantB(){return `<section class="window cinema" aria-label="方案 B 深色观画">${chrome()}<header class="cinema-header">${brand()}<nav><button data-view="today" class="${state.view==='today'?'active':''}">正在展出</button><button data-view="favorites" class="${state.view==='favorites'?'active':''}">我的收藏</button><button data-view="history" class="${state.view==='history'?'active':''}">更换记录</button><button data-action="settings">设置</button></nav><span class="pill"><i class="dot"></i>后台运行中</span></header>${state.view==='today'?`<div class="cinema-art-area">${artStage()}<div class="art-dots"><span></span><span></span><span></span></div></div><div class="cinema-meta"><div>${meta()}</div><div class="cinema-actions">${heart('icon-btn')}<button class="secondary" data-action="details">作品详情 ${icon('external')}</button><button class="primary" data-action="change">${icon('refresh')}换一幅画</button></div></div><div class="cinema-bottom"><div>${icon('clock')}<p>${state.auto?`每天 <strong>${state.time}</strong> 自动更换 · 下一次，明天 ${state.time}`:'自动更换已暂停'}</p><button class="text-btn" data-toggle="auto">${state.auto?'暂停':'恢复'}</button></div><div><span class="display-tag">${icon('monitor')}双屏 · 完整显示</span><span class="display-tag">${icon('check')}${state.landscape?'竖图已过滤':'所有画幅'}</span><button class="text-btn" data-action="settings">${icon('gear')}更换设置</button></div></div>`:collection()}${status()}</section>`;}
function VariantC(){const w=works[state.painting];return `<section class="window compact" aria-label="方案 C 轻量控制台">${chrome()}<header class="compact-header">${brand()}<span class="pill"><i class="dot"></i>正在后台守候</span></header>${state.view==='today'?`<div class="compact-body"><div class="compact-topline"><span style="font-size:12px;color:#607994">当前壁纸</span><span>已适配 2 块 4K 屏幕</span></div><div class="compact-current">${artStage()}<div class="compact-info"><h2 class="art-title">${w.title}</h2><p class="artist-line">${w.artist}<br>${w.date} · ${w.medium}</p><p class="compact-museum">${w.museum} · 公共领域</p><div class="compact-controls"><button class="primary" data-action="change">${icon('refresh')}换一幅画</button>${heart()}<button class="text-btn" data-action="details">详情 ${icon('external')}</button></div></div></div><section class="compact-auto"><div><span class="compact-clock">${icon('clock')}</span><div><h3>每天 <strong>${state.time}</strong> 自动更换</h3><p>${state.auto?`下次，明天 ${state.time} · 错过时间，开机后补换`:'已暂停，手动更换不受影响'}</p></div></div><div><button class="text-btn" data-action="settings">更换设置</button>${toggle('auto')}</div></section><div class="compact-bottom-settings"><div><span>${icon('check')}${state.landscape?'不使用竖图':'允许竖图'}</span><span>${icon('monitor')}每屏完整显示</span><span>${icon('check')}${state.startup?'随 Windows 启动':'手动启动'}</span></div><button class="text-btn" data-action="settings">管理 ${icon('gear')}</button></div>${recent()}</div>`:collection()}${status()}</section>`;}
function render(){document.body.dataset.variant=state.variant;document.body.classList.toggle('capture',params.get('capture')==='1');document.body.dataset.production=params.get('production')==='1';document.getElementById('direction-key').textContent=`方案 ${state.variant}`;document.getElementById('direction-name').textContent=variants[state.variant];document.getElementById('variant-label').textContent=`${state.variant} · ${variants[state.variant]}`;document.getElementById('prototype-root').innerHTML=({A:VariantA,B:VariantB,C:VariantC})[state.variant]();window.prototypeState={...state,favorites:[...state.favorites]};}
function setVariant(key){state.variant=key;state.view='today';const url=new URL(location.href);url.searchParams.set('variant',key);history.replaceState(null,'',url);render();console.info('Prototype variant',key,window.prototypeState);}
function cycle(step){const keys=Object.keys(variants);setVariant(keys[(keys.indexOf(state.variant)+step+keys.length)%keys.length]);}
let toastTimer;function toast(text){const node=document.getElementById('toast');node.textContent=text;node.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('visible'),2100);}
function closeModal(){document.getElementById('modal-root').innerHTML='';}
function modal(kind){const w=works[state.painting];let body,title,cls='';if(kind==='settings'){title='自动更换与显示';body=`<p>让桌面按自己的节奏，遇见下一幅画。</p>${row('auto','每天自动换一幅')}<label for="modal-time">每日更换时间</label><select id="modal-time" data-field="time">${timeOptions()}</select>${row('landscape','不使用竖图','按图片实际方向判断')}${row('startup','开机自动启动','关闭窗口后，仍在后台自动更换')}<div class="switch-row"><div class="row-title">多屏排版</div><span style="font-size:11px;color:#8a9580">每屏完整显示</span></div><button class="primary" data-action="close">完成</button>`;}else if(kind==='preview'){title='壁纸预览 · 显示器 '+state.monitor;body=`<img src="${w.image}" alt="${w.title}">`;cls='preview-dialog';}else{title='画作详情';body=`<img class="detail-image" src="${w.image}" alt="${w.title}"><h3>${w.title}</h3><p class="artist-line">${w.artist} · ${w.date}</p><p>${w.museum}<br>${w.medium} · 公共领域<br>原图尺寸 ${w.size}</p><button class="primary" data-action="close">返回画作</button>`;}document.getElementById('modal-root').innerHTML=`<div class="modal-scrim" data-scrim="true"><section class="dialog ${cls}" role="dialog" aria-modal="true" aria-label="${title}"><div class="dialog-title"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="关闭">${icon('close')}</button></div>${body}</section></div>`;document.querySelector('.dialog button')?.focus();}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button){if(event.target.dataset.scrim)closeModal();return;}if(button.dataset.cycle){cycle(Number(button.dataset.cycle));return;}if(button.dataset.view){state.view=button.dataset.view;render();return;}if(button.dataset.toggle){state[button.dataset.toggle]=!state[button.dataset.toggle];const inDialog=Boolean(button.closest('.dialog'));render();if(inDialog)modal('settings');return;}if(button.dataset.monitor){state.monitor=Number(button.dataset.monitor);render();return;}if(button.dataset.painting!==undefined){state.painting=Number(button.dataset.painting);state.view='today';render();toast('预览该画作 · 桌面壁纸未改变');return;}switch(button.dataset.action){case'change':state.painting=(state.painting+1)%works.length;render();toast('已切换原型预览，实际壁纸未改变');break;case'favorite':if(state.favorites.has(state.painting)){state.favorites.delete(state.painting);toast('已取消原型中的收藏');}else{state.favorites.add(state.painting);toast('已收藏这幅画作');}render();break;case'settings':modal('settings');break;case'preview':modal('preview');break;case'details':modal('details');break;case'close':closeModal();break;}});
document.addEventListener('change',event=>{if(event.target.dataset.field==='time'){state.time=event.target.value;render();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeModal();return;}if(event.target.closest('input,textarea,select,[contenteditable]')||document.querySelector('.modal-scrim'))return;if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();cycle(event.key==='ArrowLeft'?-1:1);}});
render();
